Module PSOCALL.

(* [comment removed for export] *)
Definition kinb (k : PSO.kind) (ks : list PSO.kind) : bool := existsb (PSO.kind_eqb k) ks.
Definition bshz_ok (i : nat) : bool := ltac2:(Rpl.RP.run_i (rplG ()) 1 "S00$i;R+0!2'1!3'2+3+3!1'4#1!1,5}^;").
Definition more1 (c : CC.cutpoint) (cells : list kentry) : bool := ltac2:(Rpl.RP.run_i (rplG ()) 2 "S00$c;R+6$cells;R!1+7+8-9RN$x;R!1+9+:+;!1'<!1'=#22$t;R+:-9RN$x;R!1+9+>+;!3'?#3#2#12$z;R+>->RN$z;R+>+;#13,@$p;R+A-ARN$p;R+A+;#13$p0;R+A,@$p0;R+A,@,B$p;R+A,@,@,@").
(* [comment removed for export] *)
Definition errh_arg (cells : list kentry) (a1 : expr) : bool :=
  match a1 with
  | EAlu Instr.ALU_ADD (EVar r) (ELit kk) =>
      (Nat.eqb r 65 && Z.eqb (kk mod 16) 0 && (32 <=? kk) && (kk + 8 <=? 1016)
       && match CAX.cell_at cells (EVar 65) kk 4 with Some (ELit v) => ((0 <=? v) && (v <? 2 ^ 31))%bool | _ => false end
       && PSO.has cells (KWord (SA (EAlu Instr.ALU_SRL (EVar 65) (ELit 3)) (2147450880 + kk / 8)) 1 (ELit 4)))%bool
  | _ => false end.
