Lemma POP_OUT : forall sb sc a, sb mod 8 = 0 -> 0 < sc -> ~ (P + 256 <= a < P + 264) -> ~ in_shadow_of sb sc a ->
  L5.outside [(P + 256, 8); (S sb, (sc + 7) / 8)] a.
