(* [comment removed for export] *)
Definition vrel (st z : Z) : bool :=
  ((PSO.inb st [1; 7; 9; 10; 11; 12; 13] && Z.eqb z st) || (Z.eqb st 5 && Z.eqb z 5) || ((Z.eqb st 9 || Z.eqb st 10) && Z.eqb z 16))%bool.
Definition vp_leaf (i : nat) (c : CC.cutpoint) (k : nat) (ps : SR.post_spec) : bool := ltac2:(Rpl.RP.run_i (rplG ()) 4 "S60}:};}2!1,52!1,^V|629;}1$i;R+0$c;R+6$k;R+0$ps;R+I&cells;R!1'J#1!1+7+8!2'E!2'E!2'E!2'E!2'E!2'E!2'E!2'L!1'M#5!3,N+O,P!1,R+O!2'1!2'S#20!3,mB,oN!1,50!1,^6!1,G|778;!2'1!2'S#21!3,mB,oN3!1,^64!1'U#5!2'1!3'_Q+3+3!1'4#5!2's9!1,G|10;!1,5}^9!1'^:#5!2'V#4#1-9RN$x;R!1+9+3+;!4'gH#13452$e;R+3-3RN$e;R+3+;#18$z;R+>!2'E-9RN$x;R!1+9+0+;!3'f='s\#7#52$j;R+0!2'H!1'c:#1#2,@-9RN$x;R!1+9+:+;!1'<!1'=#62$t;R+:-9RN$x;R!1+9+>+;!3'C#7#4#12$st;R+>!2't0#1#3,@,@$n;R+0,@$op;R+j;$a;R+3$b;R+3,@$op;R+j;$a;R+3$b;R+3,@$op;R+j<$a;R+3$b;R+3,@$op;R+j<$a;R+3$b;R+3,@$sx;R+;$lo;R+0$n;R+0$e0;R+3,@$sx;R+;$k0;R+0$i0;R+>$n;R+0,@,@").
Definition vp_chk (i : nat) (c : CC.cutpoint) (k : nat) (ps : SR.post_spec) (tg : CC.tag) : bool := ltac2:(Rpl.RP.run_i (rplG ()) 5 "S00$i;R+0$c;R+6$k;R+0$ps;R+I$tg;R+^<-^<RN$tg;R+^<+;#12$j;R+0$s;R'^=,B$pc;R+>!2'D!2'D!1'_B!2'H#1'g9!3'^>#6#3#1!4't1#6#5#4#3").
Lemma VP_all : CH2.leaves_all G.CPS G.TAGS vp_chk = true. Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S00vv!2,^@+;,B!3+^A+;!3'^B'^C'^D't2,B").
Qed.
Lemma VP : forall i c k ps0, CH2.is_leaf G.CPS G.TAGS i c k ps0 (CC.TOther VPUSH) -> PSO.dead_chk i ps0 VPUSH = false -> vp_leaf i c k ps0 = true.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S40!1,^G'g9!3'^>#8#5'g9!4't1#8#7#6#5!1'_B,B$i;R+0$c;R+6$k;R+0$ps0;R+I$IL;R!7'^F'^C'^D#4#3#2#10$Hd;R!3+^A+;!3'^>#5#2'g9,@&X;R!:'^H'^C'^D't2't3#6#5#4#30#2!3+^A+;!5't2#6#5#4#30,B&X;R!6'^J+;!2'H'g9'g9$b;R+;!3+^A+;!2'D!2'D!1'_B#112,B#1,B!1'g0'g9!3+^A+;!2'D!2'D3!3'^>#7#4'g9!4't1#7#6#5#4,B&X;R!6'^J+;1$b;R+;!3+^A+;!2'D!2'D3#1!4't1#9#8#7#6,B#1,@#3!3+^A+;!2'D!2'D3,@2,B#1").
Qed.
